// src/lib/data/timing.ts -- Sentence-level timing data loader + binary search utility + chapter navigation

import { CHAPTERS } from './chapters'

/**
 * A single sentence with its audio timing boundaries.
 * Generated by Phase 2 audio pipeline (Azure Speech wordBoundary events).
 */
export interface SentenceData {
  text: string
  start: number
  end: number
}

/**
 * Load sentence-level timing data for a chapter/language/voice combination.
 * Falls back to empty array if the timing file does not exist (graceful degradation).
 *
 * @param chapterNumber - Chapter number (0 = prologue, 1-23 = chapters)
 * @param lang - Language code ('es' or 'en')
 * @param voice - Voice gender ('female' or 'male', defaults to 'female')
 * @returns Array of SentenceData, or empty array on error/404
 */
export async function loadTimingData(
  chapterNumber: number,
  lang: 'es' | 'en',
  voice: 'female' | 'male' = 'female',
): Promise<SentenceData[]> {
  const filename = `ch${String(chapterNumber).padStart(2, '0')}.json`
  const voiceSuffix = voice === 'male' ? '-male' : ''
  const url = `/audio/timing/${lang}${voiceSuffix}/${filename}?v=3`

  try {
    const response = await fetch(url)
    if (!response.ok) return []
    const data: SentenceData[] = await response.json()
    return data
  } catch {
    // Network error, JSON parse error, or timing file doesn't exist
    return []
  }
}

/**
 * Binary search to find the sentence index at a given playback time.
 *
 * @param sentences - Sorted array of SentenceData (by start time)
 * @param currentTime - Current audio playback time in seconds
 * @returns Index of the active sentence, or -1 if in a gap between sentences
 */
export function findSentenceIndex(
  sentences: SentenceData[],
  currentTime: number,
): number {
  if (sentences.length === 0) return -1

  // Before first sentence
  if (currentTime < sentences[0].start) return -1

  // After last sentence
  const last = sentences[sentences.length - 1]
  if (currentTime >= last.end) return -1

  // Binary search: find sentence where start <= currentTime < end
  let low = 0
  let high = sentences.length - 1

  while (low <= high) {
    const mid = Math.floor((low + high) / 2)
    const sentence = sentences[mid]

    if (currentTime < sentence.start) {
      high = mid - 1
    } else if (currentTime >= sentence.end) {
      low = mid + 1
    } else {
      // start <= currentTime < end
      return mid
    }
  }

  // In a gap between sentences
  return -1
}

/**
 * Convert a URL slug to a chapter number.
 *
 * @param slug - Chapter URL slug (e.g., 'prologue', 'chapter-01')
 * @returns Chapter number (0 for prologue, parsed int for chapters)
 */
export function getChapterNumberFromSlug(slug: string): number {
  if (slug === 'prologue') return 0
  // 'chapter-NN' -> NN
  const match = slug.match(/^chapter-(\d+)$/)
  if (match) return parseInt(match[1], 10)
  return 0
}

/**
 * Load the first line of a chapter from timing data (for chapter previews).
 *
 * @param chapterNumber - Chapter number (0 = prologue, 1-23 = chapters)
 * @param lang - Language code ('es' or 'en')
 * @param voice - Voice gender ('female' or 'male', defaults to 'female')
 * @returns First sentence text, or null if timing data unavailable
 */
export async function getChapterFirstLine(
  chapterNumber: number,
  lang: 'es' | 'en',
  voice: 'female' | 'male' = 'female',
): Promise<string | null> {
  const sentences = await loadTimingData(chapterNumber, lang, voice)
  if (sentences.length > 0) return sentences[0].text
  return null
}

/**
 * Estimate chapter duration from timing data.
 * Uses the `end` value of the last sentence as an approximation.
 *
 * @param sentences - Array of SentenceData for the chapter
 * @returns Estimated duration in seconds, or 0 if no sentences
 */
export function estimateDuration(sentences: SentenceData[]): number {
  if (sentences.length === 0) return 0
  return sentences[sentences.length - 1].end
}

/**
 * Get the next chapter slug that has audio available.
 * Skips chapters with null audioFile for the given language.
 *
 * @param currentSlug - Current chapter's URL slug
 * @returns Next playable chapter slug, or null if at the end
 */
export function getNextChapterSlug(currentSlug: string): string | null {
  const idx = CHAPTERS.findIndex((ch) => ch.slug === currentSlug)
  if (idx < 0) return null

  for (let i = idx + 1; i < CHAPTERS.length; i++) {
    const ch = CHAPTERS[i]
    if (ch.audioFileEs || ch.audioFileEn) return ch.slug
  }
  return null
}

/**
 * Get the previous chapter slug that has audio available.
 * Skips chapters with null audioFile for the given language.
 *
 * @param currentSlug - Current chapter's URL slug
 * @returns Previous playable chapter slug, or null if at the beginning
 */
export function getPrevChapterSlug(currentSlug: string): string | null {
  const idx = CHAPTERS.findIndex((ch) => ch.slug === currentSlug)
  if (idx < 0) return null

  for (let i = idx - 1; i >= 0; i--) {
    const ch = CHAPTERS[i]
    if (ch.audioFileEs || ch.audioFileEn) return ch.slug
  }
  return null
}
